#!/bin/bash
# dsm-yzint14c.sh (12.11.2026, queue-ar/dsmain/yzint14c, the int14c builder for ds-main-port) -- NOT a queue item; the body of
# 57-p4zyzzzzz-ds-r92zzzzzz-ref12zzzzzz-yzint14c.sh. Log tag "RESULT yzi ", out runs/xdsm/yzint14c/x1 (YZI_OUT). A COPY of ync/dsm-ync.sh
# (19b9148d as staged; tag ync -> yzi, knobs YNC_ -> YZI_; generated by yzint14c/mkbody.py, every edit an asserted replacement; the
# original not changed; unused functions kept): the SAME start words, pins, guards and image checks (int9 .. int12 literals + int14c's),
# the same c8 / c16 harness (harness/ncmb3.py, the fixed prompt set reset per block, 35 s windows, prof12/p12win.py's wall split), the
# same staggered check (stack4/loadid.py run), cold reads (deepq.py), A11's P0 (ync/nctab.py, read in place) -- + yswl's resprobe read
# set (yswl/resprobe.py, read in place; its blockx), yd2m's A4 byte check (--mrcheck16 with the table), xpush's four-card selftest, and
# n-gram reuse (tools/ngramshare/ngshare.sh, TESTING.md BODY RULE). yzint14c/yzsum.py sums (one DECISION table).
# THE DS BASE-CANDIDATE SCREEN: image int14c = int12 bf8f557 + XPUSH (ar_xpush 63) + A4 (gg_gemv_m16 64) + A9 (ds41_bi 6) + A11 (gg_pf 2,
#   ranged GPF entries) + SWL / L2 (place_swap_lent 65, heat_min_gain_x100 66, heat_hyst_x100 67); every switch's default = int12.
#   Every lever is exact (placement / tiling / wire grouping only): every answer must be byte-identical to ref12's, alone and under load.
# P0 (before the start, no server; cards BY CHIP UUID): each failure drops ONLY that lever (a VIRHE line), the item goes on with the rest:
#   XPUSH  r4d_selftest --case ar_twoshot_4rank_exact / ar_oneshot_4rank_exact under RADIANCE_FN4_AR_XPUSH 0 and 1 on the FOUR cards
#          (ROCR_VISIBLE_DEVICES = the four R9700s' GPU-<unique_id>): rc 0, 0 FAIL, the same ok lines at 0 and 1 (each == the fp32 fold);
#          THE GATE (coordinator 13.11.: XPUSH from 1048576 elements = ~205 rows at 5120, FN 5f0352a8; every decode step <= 48 rows
#          stays lockstep, newcomer steps and prefill chunks take XPUSH): --case ar_xpush_perf at 48 / 256 / 1024 rows x 5120, each bit
#          for bit at ar_xpush 0 and 1, the first XPUSH launch at 256 rows (48 rows stayed lockstep). RADIANCE_FN4_AR_XPUSH_MIN=1048576
#          in every P0 run and in the start env; the start log's load line is read back (the bound in force), and the first XPUSH
#          launch of the run (its line names the bound) after the identity block.
#   A4     r4d_selftest --mrcheck16 on one card (YZI_P0_UUID) with A4's table mounted (yzint14c/m16-forms.txt = yd2m's P0 bench table,
#          md5 d55ad354, 95 lines; NOT re-benched): every A4 form + the switch vs the stock band, A4VERDICT PASS, the table loaded 95 of 95.
#   A11    ync's P0: --gpcheck M 1000..1537 (every GPF form vs the stock kernel) then --perfgp -> ync/nctab.py -> the ranged entries
#          (no entry = A11 out: its GATE, not a VIRHE).
#   A9 / SWL have no one-card check: the in-engine strict identities below are their proof.
# ONE FRESH START (ngshare, no ATTACH, compose guard in the item), ref12's pins exactly (read back): S5T, draft_sample 0, SP 0 / 0, M1 on,
#   IX off, draft_depth0 3, sched_row_cap 48 (fn4 CAP48), ds41_arcoded 0, CBH 0 (k 2), exl3_x3d 1, ds41_e2 1, ds41_gq 3, ds41_mix_wv 0,
#   ds41_shexp_lane 0, ds41_bi 2, gg_pf 1, KVR=1, RADIANCE_HEAT_MOVES=16, RADIANCE_PLACE_TURNOVER=0, shadow 16; MAXSEQS 16; the new
#   switches at their int12 values (ar_xpush 0, gg_gemv_m16 0, place_swap_lent 0, heat_min_gain_x100 150, heat_hyst_x100 125; none of
#   their env words at start); RADIANCE_DS41_GG_M16_FORMS=/stats/m16-forms.txt (read only under gg_gemv_m16 1) and A11's ranged entries
#   appended to RADIANCE_DS41_GG_PF_TABLE (read only under gg_pf 2).
# ARMS (in-process, fn4, read back): B = int12 / ref12; A = A9 (ds41_bi 6); G = A11 (gg_pf 2); C = A4 (gg_gemv_m16 1); W = SWL's winner
#   (place_swap_lent 1 + heat_min_gain_x100 YZI_SWLG 75: coordinator 12.11. after yswl); Z = ALL = ar_xpush 1 + gg_gemv_m16 1 + ds41_bi 6 +
#   gg_pf 2 + place_swap_lent 1 + heat_min_gain_x100 75 (a lever whose P0 failed is left out of Z).
# ORDER (coordinator: a batch-invariance failure must stop before any speed block):
#   1 IDENTITY FIRST (strict, T 0 greedy): a1-Z vs ref12's a1; a1-B vs ref12's a1 (+ a1-Z vs a1-B); gs16-Z vs a1-Z (all 16 in flight,
#     cap 48, > 48-row steps 0); A11 in range (deepq 1100 / 1300 cold, B then Z, byte-compared); STRICT staggered ld-Z vs a1-Z
#     (stack4/loadid.py run: 4 streams + the 20 probes, each joined by a FRESH 8192-token prefill 0.5 s in: mixed steps); then the
#     STRICT staggered check under A9 alone (ld-A vs a1-B: mode 6 changes how mixed steps reduce). ANY difference -> VIRHE and the item
#     STOPS before the speed blocks (logged, the engine log gzipped, the summary, exit).
#   2 PER-LEVER READS (in-process): c8 ncmb3 35 s blocks YZI_C8ORDER1 (B A G B) -- P12SPLIT newcomer ms a step (A9 / A11's target) and
#     decode ms a step (guard); A4: c16 fixed harness (ncmb3 1x16, cap 48, 35 s) B / C, then the CAP48-method c16 (cap48/ncmb.py phase
#     c16) B / C; SWL: B then W, each code, essay (switched), code, essay (switched), essay (warm) -- resprobe 512 T 0 (the res12 / yswl
#     read set; dropped FIRST when the budget is tight: yswl measured them).
#   3 ALL-ON READS: c8 YZI_C8ORDER2 (B Z Z B, P12SPLIT); c16 fixed harness Z (B from step 2); 1u essay confirm B / Z (one discarded
#     warm-up + YZI_U1N 3 back to back each, same prompt); cold YZI_CDEPTHS (136000) B / Z, the answers byte-compared.
# SUMMARY (yzint14c/yzsum.py, lines "YZSUM "): one DECISION table -- each lever vs B and ALL vs B (values, % difference, the identity /
#   staggered outcome) + the int12 references as INFO (prof1 c8 184.0, c16 fixed 217.8, c16 CAP48 300.7, 1u 91.01, cold 136k 24.57 s;
#   the XPUSH screen; yd2m): no re-runs.
# GUARDS: ync's (every switch read back, 0 request errors, the "i11" / "cbh" counters INFO, KVR read back, the A11 table line) + A4's
#   table line + the new switches' start values and range refusals + SWL's ranks (/stats place_swl / heat_min_gain_x100 a read).
#   ~38 min (P0 ~5, start ~5.5 with the n-gram fill, checks ~1, identity ~6, lever reads ~10, all-on reads ~8.5, summary ~1.5);
#   BUDGET YZI_BUDGET_MIN 45 (a section past it skipped, logged; the SWL lever reads first). NO evict, no cc_sim, no power / host / fan
#   settings; production compose files read only; nothing profiled. At the end the raw snapshots go into one tar.gz, the engine log is
#   gzipped as captured, P0 outputs gzipped, the n-gram tables cleaned (FN items follow).
# MOCK: YZI_SW=0 = a server without the int9b .. int14c switches (queue-ar/tools/mockrad): the arms post nothing new, except Z, which
#   posts ds41_shexp_lane 1 (the mock's hook: --fault differ=ds41_shexp_lane:1 makes Z's answers differ -> the stop path).
# DRYRUN=1 bash dsm-yzint14c.sh : prints every command; checks the image literals (int9 .. int12 + int14c, int12's plugin md5), every
#   helper (+ selftests), the A4 table md5, the ngramshare files, both yamls, the sidecars, the disk; no server, no GPU.
set -u
HD="$(cd "$(dirname "$0")" && pwd)"
for LIB29 in "$HOME/gpu/ds41/exl3-test/queue-29/lib-29.sh" "$HD/../../../queue-29/lib-29.sh"; do [ -e "$LIB29" ] && break; done
[ -e "$LIB29" ] && . "$LIB29" || { echo "lib-29.sh not found"; exit 1; }
QA=$HOME/gpu/ds41/exl3-test/queue-ar
Y=$HD/../ds41-stack2-tp4.yaml                   # stack2's yaml, read only (env_file ${XS2_ENVFILE}; RADIANCE_AQL_STAMP from AQLSTAMP)
TL=$QA/tools
[ -e $TL/heatsoak.sh ] && . $TL/heatsoak.sh
O=${YZI_OUT:-$R/xdsm/yzint14c/x1}; export STATSDIR=$O/stats
RD=$R/xdsm/draft; RM=$R/xdsm; RS5=$R/xdsm/stack5
export IMAGE=${YZI_IMAGE:?set YZI_IMAGE}
ITEM=${YZI_ITEM:-57-p4zyzzzzz-ds-r92zzzzzz-ref12zzzzzz-yzint14c}
PSKK=8; BIC=3; NOA=2; OCC=6; OCCK=32; DSA=0; HBR=0; HBRANKS=1,2      # stack5's S5T values, draft_sample 0 (the ARC screen's base)
SW=${YZI_SW:-1}
PLAN=""; PLAN2=""; PLAN3=""   # no lever groups: the reference reads (refreads)
F4V=${YZI_F4:-0}; F4G=${YZI_F4G:-0}; MXC=${YZI_MXCONFIRM:-0}; NTOK=${YZI_NTOK:-64}; DEPTHS=${YZI_DEPTHS:-}; GSC=${YZI_GSCONC:-16}
I11DIR=${YZI_I11DIR:-$R/xdsm/i11u}; I11ID=${YZI_I11ID:-$R/xdsm/i11u/x1u-a-O.jsonl}; R12S=$HD/../prof12/p12win.py; YDS=$HD/yzsum.py; NCT=$HD/../ync/nctab.py; C48N=$HD/../cap48/ncmb.py; C48REF=${YZI_C48REF:-300.7}; C16DUR=${YZI_C16DUR:-30}; C16WARM=${YZI_C16WARM:-10}; NREADS=${YZI_NREADS:-3}
CBHK=${YZI_CBHK:-2}; EPR=${YZI_EPROMPTS:-essay,code}
MXV=${YZI_MX:-12}; EGEN=${YZI_EGEN:-512}; ARCV=0; DOID=0; STAMPN=0
MHC=${YZI_MHC:-1}; D0=${YZI_D0:-3}; CAP=${YZI_CAP:-48}; SPN=0; SPK=0
DOD=${YZI_D:-1}
P0=""   # no lever P0 (p0sel); A11's own P0 on one card (by chip UUID): p0nc
# lever A11's P0 (the byte check, then the bench -> nctab.py's ranged entries) and its in-range identity; A11ON 0 drops arms G / N
A11CMS=${YZI_A11CMS:-1000,1104,1105,1216,1408,1535,1536,1537}; A11MS=${YZI_A11MS:-1024,1104,1216,1408}; A11IT=${YZI_A11IT:-30}
A11RANGE=${YZI_A11_RANGE:-1000-1536}; A11MIN=${YZI_A11_MIN_PCT:-1.0}; A11ID=${YZI_A11ID-1100 1300}; P0PERFS=${YZI_P0PERFS:-600}; P0CHECKS=${YZI_P0CHECKS:-600}
A11ON=1; A11ENT=""; GATEWHY=""; IDBAD=""   # IDBAD: arms whose strict identity failed (never "best")
LDCONC=${YZI_LDCONC:-4}; LDPF=${YZI_LDPF:-8192}; STAGN=${YZI_STAGN:-1}; STAGB=${YZI_STAGB:-0}   # the staggered-arrival identity (zepb's epbstag): streams, fresh prefill tokens
CDEPTHS=${YZI_CDEPTHS-136000}; NTOK=${YZI_NTOK:-64}
PFOK=0; A10=0; PDEPTHS=""   # (yd2m's lever A10: not in this item)
XPON=1; A4ON=1; IDFAIL=""; STOPPED=0   # int14c: a lever whose P0 fails is dropped (XPON / A4ON / A11ON 0); IDFAIL = the failed strict identities (THE STOP)
SWLON=${YZI_SWL:-1}; SWLG=${YZI_SWLG:-75}; SWLREADS=${YZI_SWLREADS:-1}   # SWL in Z + its reads (coordinator 12.11. after yswl: L1G075 = place_swap_lent 1 + heat_min_gain_x100 75)
C8ORD1=${YZI_C8ORDER1-BAGB}; C8ORD2=${YZI_C8ORDER2-BZZB}; U1N=${YZI_U1N:-3}; ALLEST=${YZI_ALLEST:-9}   # step 2 c8, step 3 c8, 1u reads an arm, step 3 minutes (kept when the SWL reads are weighed)
A4TAB=$HD/m16-forms.txt; A4MD5=${YZI_A4MD5:-d55ad354}; A4N=${YZI_A4N:-95}; REF12A1=${YZI_REF12A1:-$R/xdsm/ref12/xref12-a1.jsonl}   # A4's table = yd2m's P0 bench (not re-benched); ref12's a1
NGS=$HOME/gpu/ds41/exl3-test/queue-ar/tools/ngramshare; NGB=0; NGCLEAN=0; NGDIR=${NGSHARE_DIR:-/dev/shm/ds41ng}   # n-gram reuse (TESTING.md BODY RULE)
SARM=BASE   # yswl's blockx names the start arm (one start here)
XPMIN=${YZI_XPMIN:-1048576}; XPROWS=${YZI_XPROWS:-48,256,1024}   # XPUSH's bound (coordinator 13.11., FN 5f0352a8; RADIANCE_FN4_AR_XPUSH_MIN at start) and the P0 gate check's rows x 5120
case $XPMIN in ''|*[!0-9]*) echo "YZI_XPMIN is an element count"; exit 1 ;; esac; case $XPROWS in *[!0-9,]*|'') echo "YZI_XPROWS rows, comma separated"; exit 1 ;; esac
[ -n "$(echo $XPROWS | tr ',' '\n' | awk -v m=$XPMIN '$1 * 5120 >= m' | head -1)" ] && [ -n "$(echo $XPROWS | tr ',' '\n' | awk -v m=$XPMIN '$1 * 5120 < m' | head -1)" ] || { echo "YZI_XPROWS needs a size below and one above YZI_XPMIN (x 5120)"; exit 1; }
case $SWLON$SWLREADS in [01][01]) ;; *) echo "YZI_SWL / YZI_SWLREADS take 0 or 1"; exit 1 ;; esac
for v in $SWLG $U1N $ALLEST $A4N; do case $v in ''|*[!0-9]*) echo "a knob is not a number ('$v')"; exit 1 ;; esac; done
[ $SWLG -le 10000 ] || { echo "YZI_SWLG 0..10000 (heat_min_gain_x100)"; exit 1; }
case $C8ORD1 in *[!BAG]*|'') echo "YZI_C8ORDER1 takes B, A (A9) and G (A11) (got '$C8ORD1')"; exit 1 ;; esac
case $C8ORD2 in *[!BZ]*|'') echo "YZI_C8ORDER2 takes B and Z (ALL) (got '$C8ORD2')"; exit 1 ;; esac
case $A11CMS$A11MS in *[!0-9,]*|'') echo "YZI_A11CMS / YZI_A11MS rows, comma separated"; exit 1 ;; esac
case $A11RANGE in [0-9]*-[0-9]*) ;; *) echo "YZI_A11_RANGE LO-HI"; exit 1 ;; esac
[ ${A11RANGE%-*} -ge 49 ] && [ ${A11RANGE#*-} -ge ${A11RANGE%-*} ] || { echo "YZI_A11_RANGE: 49 <= LO <= HI"; exit 1; }
for v in $A11IT $P0PERFS $P0CHECKS $LDCONC $LDPF $STAGN $STAGB $A11ID $CDEPTHS; do case $v in ''|*[!0-9]*) echo "a P0 / reading knob is not a number ('$v')"; exit 1 ;; esac; done
case $A11MIN in ''|*[!0-9.]*) echo "YZI_A11_MIN_PCT is a percentage"; exit 1 ;; esac
CORD=${YZI_CORDER-}; C8ORD=${YZI_C8ORDER-BAGNGAB}; U1ORD=${YZI_U1ORDER-}; C16ORD=${YZI_C16ORDER-BX}; DECTH=${YZI_DECTH:-1.0}; P0MIN=${YZI_P0MIN:-12}
for o in "$CORD" "$U1ORD"; do case $o in *[!BAGN]*) echo "YZI_U1ORDER takes B A G N (got '$o')"; exit 1 ;; esac; done
case $C16ORD in *[!BAGNX]*) echo "YZI_C16ORDER takes B A G N and X (= the best arm by c8) (got '$C16ORD')"; exit 1 ;; esac
case $C8ORD in *[!BAGN]*|'') echo "YZI_C8ORDER takes B, A (A9), G (A11) and N (both) (got '$C8ORD')"; exit 1 ;; esac
case $DECTH in ''|*[!0-9.]*) echo "YZI_DECTH is a percentage (got '$DECTH')"; exit 1 ;; esac
case $P0MIN in ''|*[!0-9]*) echo "YZI_P0MIN a number"; exit 1 ;; esac
DISKMIN=${YZI_DISKMIN_MB:-11000}; BUDGET=${YZI_BUDGET_MIN:-45}; ALLOWOLD=${YZI_DRY_ALLOW_OLD:-0}
SIDE=${YZI_SIDECAR:-dspark-dlw-q8_0.rad}; SIDESHA=${YZI_SIDESHA:-f1ae116c8e07f69ab98520f6f19b73e7b7f576e72ac36484694e56fb6acdf681}
MT=192; SEED=1234
case $SW in 0|1) ;; *) echo "YZI_SW is 1 (the item) or 0 (a server without the int9b / int10 / int11 switches: the mock) (got '$SW')"; exit 1 ;; esac
for v in $MXV $EGEN $ARCV $DOID $STAMPN $MHC $D0 $CAP $DOD $DISKMIN $BUDGET $CBHK ${YZI_C8WIN:-35} ${YZI_C8WARM:-10} ${YZI_C4WIN:-20} ${YZI_C4WARM:-8} ${YZI_C1WIN:-20} ${YZI_C1WARM:-6} ${YZI_CSPACING:-6} ${YZI_C8X:-0} ${YZI_C4ID:-0} ${YZI_C8GENS:-0}; do case $v in ''|*[!0-9]*) echo "a numeric knob is not a number ('$v')"; exit 1 ;; esac; done
case $MXV in 0|12|16|24) ;; *) echo "YZI_MX 0 / 12 / 16 / 24 (ds41_mix_wv's values)"; exit 1 ;; esac
case $F4V in ''|*[!0-9]*) echo "YZI_F4 0 / 1 / 2..64 (ds41_shexp_lane)"; exit 1 ;; esac; [ $F4V -le 64 ] || { echo "YZI_F4 0..64"; exit 1; }
[ $F4V -le 1 ] || [ $F4G = 1 ] || { echo "YZI_F4 $F4V (a row threshold) needs the F4G image: set YZI_F4G=1 (its literal is then checked)"; exit 1; }
for v in $F4G $MXC $NTOK $GSC; do case $v in ''|*[!0-9]*) echo "a numeric knob is not a number ('$v')"; exit 1 ;; esac; done
for v in $DEPTHS; do case $v in ''|*[!0-9]*) echo "YZI_DEPTHS takes token counts (got '$v')"; exit 1 ;; esac; done
[ -z "${YZI_MAXSEQS:-}" ] || case ${YZI_MAXSEQS} in *[!0-9]*) echo "YZI_MAXSEQS a number"; exit 1 ;; esac
[ $ARCV -le 1048576 ] || { echo "YZI_ARC 0..1048576 (ds41_arcoded's values)"; exit 1; }
[ $EGEN -ge 64 ] || { echo "YZI_EGEN >= 64"; exit 1; }
[ $D0 -le 3 ] || { echo "YZI_D0 0..3"; exit 1; }
[ $CAP -le 4096 ] || { echo "YZI_CAP 0..4096"; exit 1; }
[ $MHC -le 1048576 ] || { echo "YZI_MHC 0..1048576 (mhc_fuse's values)"; exit 1; }
case ${YZI_C8TH:-1.0} in ''|*[!0-9.]*) echo "YZI_C8TH is a percentage (got '${YZI_C8TH:-}')"; exit 1 ;; esac
[ $CBHK -ge 2 ] && [ $CBHK -le 64 ] || { echo "YZI_CBHK 2..64 (sched_cb_hold_k)"; exit 1; }
for e in ${YZI_C8PLAN-S:O}; do case $e in [SC]:O|[SC]:N|[SC]:H[0-9]*) ;; *) echo "YZI_C8PLAN entries are S|C:O|N|H<ms> (got '$e')"; exit 1 ;; esac; done
case $EPR in essay|essay,code) ;; *) echo "YZI_EPROMPTS essay or essay,code (got '$EPR')"; exit 1 ;; esac
for o in "${YZI_C1ORDER-OO}" "${YZI_C4ORDER-OO}"; do case $o in *[!ON]*) echo "the c1 / c4 orders take O and N (got '$o')"; exit 1 ;; esac; done
for c in $P0; do case $c in *:*[!0-9:]*|*::*|*:*:*:*) echo "YZI_P0 takes case:min_ok:seconds (got '$c')"; exit 1 ;; esac; done
for g in $PLAN $PLAN2 $PLAN3; do
  case ${g%%:*} in MX|MX12|GQ|E2|F4|C1T) ;; *) echo "YZI_PLAN groups are MX MX12 GQ E2 F4 C1T (got '${g%%:*}')"; exit 1 ;; esac
  for a in $(echo ${g#*:} | tr ',' ' '); do case $a in O|MX|MX12|GQ|E2|F4|N|NH|H[0-9]*|C[1-9][0-9]|C5) ;; *) echo "YZI_PLAN arm '$a' unknown (O MX MX12 GQ E2 F4 N C5..C95)"; exit 1 ;; esac; done
done
GS=$HOME/gpu/ds41/exl3-test/queue/tools/greedyset.py
S4=$HD/../stack4
LD=$S4/loadid.py                                                                                    # stack4's, read only
CTR=$HD/../i9b/i9bctr.py                                                                            # i9b's (INFO only), read only
NCMB=$HD/../nc/ncmb.py                                                                              # nc's, read only (its selftest only)
MBT2=$HD/../harness/mbt3.py; NCMB2=$HD/../harness/ncmb3.py; C8MIX=$HD/../harness/c8mix.py          # the harness (read only): c1 / c4 / c8 on mbt3's fixed schedule + FIXED PROMPT SET (TESTING.md 12.11. c4 METHOD FIX)
C4R=$HD/../c4lev/c4rows.py                                                                          # c4lev's: the step log by a step's rows, read in place
DQ=$QA/deepq.py; MBP=$D/mb.py; TESTS=$D/ds41_tests.py; SPB=$HD/../yswl/resprobe.py; SPB0=$D/stepprobe.py   # resprobe = stepprobe + the answer text (yswl's, read in place)
MBT=$S4/mbt.py; EP=$S4/editprobe.py; PRB=$S4/sdprobe.py                                            # stack4's, read only (d0blocks.py args)
D0B=$HD/../d0ab/d0blocks.py                                                                         # d0ab's (+ its s5ctr.py beside it), read only
U1S=$HD/../1u/u1sum.py                                                                              # the screen's (steps by verify rows), read in place
M225=deepseek-v4.1-flash-1017-exl3-2.25bpw.rad
WARM_REF_225=$R/x117/guard/x117-best524-warm-q.txt
T00=$(date +%s); NV=0
xlog() { case "$*" in *VIRHE*) NV=$((NV + 1)) ;; esac; log "RESULT yzi $*"; }
elapsed() { echo $(( ($(date +%s) - T00) / 60 )); }
# ---------------------------------------------------------------- the start (= the ARC screen's + RADIANCE_DS41_GQ=3 + RADIANCE_DS41_E2=1; KVR off)
GPTAB=q6_K:8192x1280=426,q6_K:5120x2048=426,q6_K:5120x768=426,q6_K:5120x512=426,q6_K:25600x6144=426,q8_0:5120x768=422,q8_0:5120x512=422
SIDECAR=dspark-conf.f32
LEVENV="RADIANCE_DS41_GG_PF=1 RADIANCE_DS41_GG_PF_TABLE=$GPTAB RADIANCE_DS41_F32_PF=25 RADIANCE_DS41_ARENA_DECODE_ROWS=8,48
  RADIANCE_DS41_ROUTER_BF16=1 RADIANCE_DS41_EMB_RAM=1 RADIANCE_PLACE_SHADOW_SLOTS=16 RADIANCE_XPREFETCH=0 RADIANCE_DS41_DSPARK_WALK=1
  RADIANCE_DS41_ARGATHER_MAX=48 RADIANCE_DS41_QNFOLD=1 RADIANCE_DS41_SWFOLD=1 RADIANCE_DRAFT_CTXSKIP=0 RADIANCE_DS41_DSPARK_CONF=/models/$SIDECAR
  RADIANCE_DRAFT_LEND=0 RADIANCE_DRAFT_PROBE_BACKOFF=0 RADIANCE_DRAFT_LEND_BORROW=0 RADIANCE_DRAFT_SAMPLE=0 RADIANCE_WEIGHT_SIDECAR=/models/$SIDE
  RADIANCE_DS41_BI=0 RADIANCE_DRAFT_CTXSKIP_SLOTS=129 RADIANCE_DRAFT_LEND_WEIGHTS=0 RADIANCE_DS41_PSK=0
  RADIANCE_LOG_STEPS=1 RADIANCE_DS41_ENGDD=0 RADIANCE_PLACE_HB_RANKS=$HBRANKS
  RADIANCE_DS41_MHC_FUSE=0 RADIANCE_DS41_GQ=3 RADIANCE_DS41_E2=1 RADIANCE_DS41_KV_REPLICATED=1"
