    blockx U1W O essay || true
    for k in $(seq 1 $NREADS); do stopfile && return 0; blockx U1 O essay || true; done
  fi
  stopfile && return 0
  budok "c8 block (fixed harness, wall split)" 2 && { mbx 8 1 O S || true; }
