  while IFS= read -r l; do xlog "${l:0:1800} | NOTE MAXSEQS ${MAXSEQS:-?} vs ref12's 8"; done < <(grep -h '^P12CONFIRM' $O/confirm.txt 2>/dev/null)
  python3 -c 'import json,sys
o = sys.argv[1]; W = []
for l in open(sys.argv[2]):
    d = json.loads(l)
    if d.get("lever") not in ("U1", "U1W"): continue
    n = "r%d-%s" % (d["i"], d["lever"]); b = "b%d-%s-%s" % (d["i"], d["lever"], d["arm"])
    W += ["--win", "%s:%.6f:%.6f" % (n, d["utc0"], d["utc1"]), "--st", "%s:%s/st-%s-0.json:%s/st-%s-1.json:%.6f:%.6f" % (n, o, b, o, b, d["utc0"], d["utc1"])]
print("\n".join(W))' $O $O/blocks.jsonl > $O/u1win.args 2>/dev/null
  [ -s $O/u1win.args ] && { mapfile -t W < $O/u1win.args; timeout 300 python3 -I -B $R12S rows $EL "${W[@]}" --json $O/u1rows.json > $O/u1rows.txt 2>&1; }
  while IFS= read -r l; do xlog "1u ${l:0:1500}"; done < <(grep -h '^P12ROWS' $O/u1rows.txt 2>/dev/null)
  w8=$(mwin $O/c8/c8-1-S-O-reqs.jsonl)
  if [ -n "$w8" ]; then
    timeout 300 python3 -I -B $R12S split $EL --win c8:$w8 --mbline $O/c8/c8-1-S-O.txt --sw0 $O/c8/c8-1-S-O-st-w0.json --sw1 $O/c8/c8-1-S-O-st-w1.json --target 200 --ref "ref12 c8:8.28:36.1:0.803:184.5" > $O/c8split.txt 2>&1
    timeout 300 python3 -I -B $R12S rows $EL --win c8:$w8 --json $O/c8rows.json > $O/c8rows.txt 2>&1
    while IFS= read -r l; do xlog "c8 ${l:0:2400} | NOTE MAXSEQS ${MAXSEQS:-?} vs ref12's 8"; done < <(grep -hE '^P12(SPLIT|ROWS)' $O/c8split.txt $O/c8rows.txt 2>/dev/null)
  else xlog "summary: c8 -- no window (no marks in $O/c8/c8-1-S-O-reqs.jsonl)"; fi
  w16=$(mwin $O/c8/c16-cap-reqs.jsonl)
  if [ -n "$w16" ]; then
    timeout 300 python3 -I -B $R12S rows $EL --win c16:$w16 --json $O/c16rows.json > $O/c16rows.txt 2>&1
    timeout 300 python3 -I -B $R12S split $EL --win c16:$w16 --mbline $O/c8/c16-cap.txt --sw0 $O/c8/c16-cap-st-w0.json --sw1 $O/c8/c16-cap-st-w1.json --target 200 > $O/c16split.txt 2>&1
    while IFS= read -r l; do xlog "c16 ${l:0:2400}"; done < <(grep -hE '^P12(SPLIT|ROWS)' $O/c16rows.txt $O/c16split.txt 2>/dev/null)
  else xlog "summary: c16 -- no window (no marks in $O/c8/c16-cap-reqs.jsonl)"; fi
  if [ -s $O/gs$GSC.win ]; then
    read -r u0 u1 < $O/gs$GSC.win
    timeout 300 python3 -I -B $R12S rows $EL --win gs$GSC:$u0:$u1 --json $O/gsrows.json > $O/gsrows.txt 2>&1
    while IFS= read -r l; do xlog "gs$GSC step log (the > 48-row count must be 0 under the cap) ${l:0:1500}"; done < <(grep -h '^P12ROWS' $O/gsrows.txt 2>/dev/null)
    python3 -c 'import json,sys; d = json.load(open(sys.argv[1]))["windows"]; w = list(d.values())[0]; sys.exit(0 if w.get("gt48", 0) == 0 else 1)' $O/gsrows.json 2>/dev/null \
      || { [ $SW = 1 ] && xlog "gs$GSC step log: VIRHE > 48-row decode steps under the cap (or no step-log reading)" || xlog "gs$GSC step log: INFO > 48-row steps (SW=0 mock: no row cap emulated)"; }
  fi
  grep -lq '^Traceback' $O/confirm.txt $O/u1rows.txt $O/c8split.txt $O/c8rows.txt $O/c16rows.txt $O/c16split.txt 2>/dev/null && xlog "summary: VIRHE a Traceback in the analysis ($(grep -h -A4 '^Traceback' $O/confirm.txt $O/u1rows.txt $O/c8split.txt $O/c8rows.txt $O/c16rows.txt $O/c16split.txt 2>/dev/null | tail -2 | tr '\n' ' ' | cut -c1-300))"
  return 0
}
# ---------------------------------------------------------------- levers A9 / A11's own functions (P0 on one card, the table line, identity, readings, summary)
P0UUID=${YZI_P0_UUID:-GPU-dbba5c851cfef7b3}   # P0's card BY CHIP UUID (ROCR_VISIBLE_DEVICES; gpu02 sysfs unique_id dbba5c851cfef7b3 = card4, 03:00.0)
DEV1="--network none --device /dev/kfd --device /dev/dri --security-opt seccomp=unconfined --ulimit memlock=-1 --ipc=host -e ROCR_VISIBLE_DEVICES=$P0UUID"
p0nc() {   # p0nc: ONE card (P0UUID), no server -- (1) the byte check r4d_selftest --gpcheck A11CMS (every GPF form vs the stock WMMA kernel,
           # every DS dense shape) -> GPVERDICT PASS; (2) the bench --perfgp A11MS A11IT -> nctab.py -> the ranged entries A11ENT (p0-tab.txt).
           # A failure or no entry sets A11ON=0 (arm G and Z's gg_pf 2 dropped; a check failure is a VIRHE line, no entry the GATE); A9 goes on. -> 0
  local c=$O/p0-check.txt f=$O/p0-perf.txt rc v nchk nfail
  run "gpurun yzi-p0-check-$$ $P0CHECKS $DEV1 --entrypoint /opt/radiance/bin/r4d_selftest $IMAGE /opt/radiance/share/radiance/kernels/libr4d.so --gpcheck $A11CMS > $c 2>&1"; rc=$?
  if [ "$DRY" = 1 ]; then
    echo "+ RESULT yzi P0 byte check (one card $P0UUID, bounded $P0CHECKS s, M $A11CMS): rc 0, every GPCHECK line 'identical in every form', GPVERDICT check ... PASS (byte-identical, every form) -- else VIRHE and A11 (arm G, Z's gg_pf 2) DROPPED, A9 goes on"
  else
    nchk=$(grep -c '^GPCHECK .*identical in every form' $c); nfail=$(grep -c '^  FAIL\|DIFFERS' $c); v=$(grep -m1 '^GPVERDICT check' $c)
    xlog "P0 byte check (r4d_selftest --gpcheck, one card $P0UUID, M $A11CMS): rc $rc, $nchk GPCHECK lines identical in every form, $nfail FAIL / DIFFERS | ${v:-no GPVERDICT line}"
    case "$v" in *"PASS (byte-identical, every form)"*) [ $rc = 0 ] && [ $nfail = 0 ] || v="" ;; *) v="" ;; esac
    if [ -z "$v" ]; then
      if [ $SW = 0 ]; then xlog "P0: failed under YZI_SW=0 (a mock run: docker run --device is not emulated) -- the mock goes on"
      else A11ON=0; xlog "P0 byte check: VIRHE not PASS -> A11 (arm G, Z's gg_pf 2) DROPPED, A9 goes on | $(grep -E '^  FAIL|DIFFERS|error|fault|stopped after' $c | head -5 | cut -c1-300 | tr '\n' ';')"; fi
    fi
    gzip -f $c 2>/dev/null || true
  fi
  [ $A11ON = 1 ] || return 0
  run "gpurun yzi-p0-perf-$$ $P0PERFS $DEV1 --entrypoint /opt/radiance/bin/r4d_selftest $IMAGE /opt/radiance/share/radiance/kernels/libr4d.so --perfgp $A11MS $A11IT > $f 2>&1"; rc=$?
  run "timeout 60 python3 -I -B $NCT $f --gptab $GPTAB --range $A11RANGE --min-pct $A11MIN --out $O/p0-tab.entries > $O/p0-tab.txt 2>&1"
  if [ "$DRY" = 1 ]; then
    echo "+ RESULT yzi P0 bench (--perfgp M $A11MS, $A11IT launches, bounded $P0PERFS s) -> nctab.py: NCTAB lines (int12's pick vs the best identical form, summed over the Ms) + NCTABLE <entries> -> A11ENT; no entry = A11's GATE (G / N dropped, not a VIRHE)"
    A11ENT="q6_K:5120x2048@$A11RANGE=0"; return 0
  fi
  A11ENT=$(cat $O/p0-tab.entries 2>/dev/null)
  while IFS= read -r l; do xlog "P0 bench ${l:0:500}"; done < <(grep -E '^NCTAB' $O/p0-tab.txt | head -60)
  while IFS= read -r l; do xlog "P0 bench ${l:0:300}"; done < <(grep -E '^GPVERDICT|^GPTAB' $f)
  if [ $rc != 0 ] || ! grep -q '^GPVERDICT perf: .*bytes identical everywhere' $f || grep -q 'NCTAB VIRHE' $O/p0-tab.txt; then
    if [ $SW = 0 ]; then xlog "P0 bench: failed under YZI_SW=0 (a mock) -- the mock goes on with a stand-in entry"; A11ENT="q6_K:5120x2048@$A11RANGE=0"; return 0; fi
    A11ON=0; A11ENT=""; xlog "P0 bench (r4d_selftest --perfgp): VIRHE rc $rc, $(grep -m1 '^GPVERDICT perf' $f || echo 'no GPVERDICT perf line') | $(grep -E 'OUTPUT DIFFERS|FAIL|error|fault|stopped after' $f | head -3 | cut -c1-300 | tr '\n' ';') -> A11 DROPPED"
    return 0
  fi
  gzip -f $f 2>/dev/null || true
  [ -n "$A11ENT" ] || { A11ON=0; GATEWHY="the bench found no form >= $A11MIN % faster than int12's pick at M $A11MS"; xlog "A11 GATE: $GATEWHY -> arm G not run, Z keeps gg_pf 1 (the bench is A11's reading)"; return 0; }
  xlog "P0: A11's ranged entries ($(echo "$A11ENT" | tr ',' '\n' | grep -c .)): $A11ENT"
  return 0
}
a11line() {   # a11line TAG: the start log's "lever A11 (GPF-1k): N row-ranged entries" with N = the P0 entries (none when A11 is off)
