  elif [ $SW = 0 ]; then xlog "$1 A11 table: INFO (YZI_SW=0 mock) '${l:-no line}'"
  else xlog "$1 A11 table: VIRHE '${l:-no line}' vs the P0's ${w:-?} entries"; return 1; fi
}
idok() {   # idok KEY ...: each identity.txt line yzi-KEY must be IDENTICAL (strict, T 0 greedy), else VIRHE + the key into IDFAIL (THE STOP)
